sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.view = 'form';
    c.submitting = false;
    c.serverErrors = [];

    c.form = {
        short_description: '',
        description: '',
        exception_type: '',
        location: '',
        severity: ''
    };

    c.submit = function() {
        c.serverErrors = [];

        // Client-side validation
        if (!c.form.short_description || !c.form.short_description.trim()) {
            c.serverErrors.push('Short Description is required.');
        }
        if (!c.form.exception_type) {
            c.serverErrors.push('Exception Type is required.');
        }
        if (!c.form.severity) {
            c.serverErrors.push('Severity is required.');
        }
        if (c.serverErrors.length > 0) return;

        c.submitting = true;
        c.data.action = 'create';
        c.data.short_description = c.form.short_description;
        c.data.description = c.form.description;
        c.data.exception_type = c.form.exception_type;
        c.data.location = c.form.location;
        c.data.severity = c.form.severity;

        c.server.update().then(function() {
            c.submitting = false;
            var result = c.data.submitResult;
            if (result && result.success) {
                c.view = 'success';
                c.data.action = null;
            } else if (result && result.errors) {
                c.serverErrors = result.errors;
                c.data.action = null;
            }
        });
    };

    c.reset = function() {
        c.form = {
            short_description: '',
            description: '',
            exception_type: '',
            location: '',
            severity: ''
        };
        c.serverErrors = [];
        c.view = 'form';
    };

    c.viewDetail = function() {
        if (c.data.submitResult && c.data.submitResult.sys_id) {
            window.location.href = '?id=x_1956908_wareho_0_detail&record_id=' + c.data.submitResult.sys_id;
        }
    };
};

sp_widget.css:
.create-exc-widget {
  max-width: 800px;
  margin: 0 auto;
}

.create-header {
  background-color: $brand-primary;
  color: #fff;
  border: none;
}

.create-header .panel-title {
  font-weight: 600;
  color: #fff;
}

.form-actions {
  padding-top: 15px;
  border-top: 1px solid #eee;
  margin-top: 10px;
}

.success-view {
  padding: 40px 20px;
}

.success-view .fa-check-circle {
  margin-bottom: 15px;
}

.exc-number {
  color: $brand-primary;
  font-weight: 700;
}

sp_widget.script:
(function() {
    var tableName = 'x_1956908_wareho_0_exception';
    data.submitResult = null;

    // Exception type choices
    data.typeChoices = [
        { value: 'damaged_goods', label: 'Damaged Goods' },
        { value: 'inventory_mismatch', label: 'Inventory Mismatch' },
        { value: 'equipment_malfunction', label: 'Equipment Malfunction' },
        { value: 'process_error', label: 'Process Error' }
    ];

    // Severity choices
    data.severityChoices = [
        { value: 'critical', label: 'Critical' },
        { value: 'high', label: 'High' },
        { value: 'medium', label: 'Medium' },
        { value: 'low', label: 'Low' }
    ];

    // Handle form submission
    if (input && input.action === 'create') {
        var errors = [];
        if (!input.short_description || (input.short_description + '').trim() === '') {
            errors.push('Short Description is required.');
        }
        if (!input.exception_type) {
            errors.push('Exception Type is required.');
        }
        if (!input.severity) {
            errors.push('Severity is required.');
        }

        if (errors.length > 0) {
            data.submitResult = { success: false, errors: errors };
            return;
        }

        var gr = new GlideRecord(tableName);
        gr.initialize();
        gr.setValue('short_description', (input.short_description + '').trim());
        gr.setValue('description', (input.description || '').trim());
        gr.setValue('exception_type', input.exception_type);
        gr.setValue('location', (input.location || '').trim());
        gr.setValue('severity', input.severity);
        gr.setValue('reported_by', gs.getUserID());
        gr.setValue('status', 'new');

        var sysId = gr.insert();
        if (sysId) {
            data.submitResult = {
                success: true,
                sys_id: sysId + '',
                number: gr.getValue('number')
            };
        } else {
            data.submitResult = { success: false, errors: ['Failed to create record. Check permissions.'] };
        }
    }
})();
